def run(d, A):
    ln = d['books']['crimpro'].setdefault('levelNotes', {})
    n = 0
    for key, (topic, lec, text) in LEVELS.items():
        ln[key] = [{'id': 'lvl-crimpro-%s' % key.replace(' > ', '_').replace(' ', ''), 'topic': topic, 'text': text, 'source': src(lec)}]
        n += 1
    print('levelNotes keys', n)
